import { Table, TableNameColumn, IntegerColumn, StringColumn, GuidColumn, FloatColumn } from '@servicenow/sdk/core'

export const sysevent_register = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'event_name',
    extends: 'sys_metadata',
    label: 'Event Registration',
    name: 'sysevent_register',
    schema: {
        table: TableNameColumn({
            attributes: {
                allow_public: true,
            },
            label: 'Table',
        }),
        priority: IntegerColumn({
            default: '100',
            label: [
                {
                    hint: 'Priority defines the order in which messages will be processed. Lower the value, higher the priority.',
                    label: 'Priority',
                    plural: 'Priorities',
                    language: 'en',
                },
            ],
        }),
        caller_access: StringColumn({
            attributes: {
                update_exempt: true,
            },
            dropdown: 'dropdown_with_none',
            label: 'Caller Access',
        }),
        queue: StringColumn({
            label: [
                {
                    hint: 'Queues are registered under Queue Registry page',
                    label: 'Queue',
                    plural: 'Queues',
                    language: 'en',
                    url: '/sysevent_queue_list.do',
                },
            ],
        }),
        suffix: StringColumn({
            label: 'Suffix',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        derived_priority: FloatColumn({
            default: '100',
            label: 'Derived priority',
            maxLength: 40,
            readOnly: true,
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 100,
        }),
        fired_by: StringColumn({
            label: 'Fired by',
            maxLength: 100,
        }),
        event_name: StringColumn({
            label: 'Event name',
        }),
    },
    textIndex: true,
})
